import{_ as a,o as i,c as s,ax as t}from"./chunks/framework.Bnt0oLax.js";const u=JSON.parse('{"title":"Automate with CI and AI","description":"Drive the Developer Studio CLI from CI pipelines and AI agents using --json output, non-interactive flags, and exit codes.","frontmatter":{"description":"Drive the Developer Studio CLI from CI pipelines and AI agents using --json output, non-interactive flags, and exit codes."},"headers":[],"relativePath":"cli/automate-with-ci-and-ai.md","filePath":"cli/automate-with-ci-and-ai.md"}'),n={name:"cli/automate-with-ci-and-ai.md"};function o(d,e,r,l,h,c){return i(),s("div",null,[...e[0]||(e[0]=[t(`<div style="display:none;" hidden data-nosnippet>Are you an LLM? You can read better optimized documentation at /docs/cli/automate-with-ci-and-ai.md for this page in Markdown format</div><h1 id="automate-with-ci-and-ai" tabindex="-1">Automate with CI and AI <a class="header-anchor" href="#automate-with-ci-and-ai" aria-label="Permalink to &quot;Automate with CI and AI&quot;">​</a></h1><p>Use this guide when you want to run <code>gsds</code> unattended — in a CI pipeline, from an AI agent, or from a script — and need every input as a flag and every output as machine-readable JSON.</p><h2 id="the-automation-contract" tabindex="-1">The automation contract <a class="header-anchor" href="#the-automation-contract" aria-label="Permalink to &quot;The automation contract&quot;">​</a></h2><p>Two guarantees make <code>gsds</code> scriptable:</p><ul><li><strong>Every interactive path has a flag equivalent.</strong> In a non-TTY environment, commands that would prompt fail fast instead, and the error names which flag is missing.</li><li><strong>Every human output has <code>--json</code>.</strong> Add <code>--json</code> to any command that prints information and you get a stable, documented structure instead of a formatted table.</li></ul><h2 id="exit-codes" tabindex="-1">Exit codes <a class="header-anchor" href="#exit-codes" aria-label="Permalink to &quot;Exit codes&quot;">​</a></h2><p>Commands exit <code>0</code> on success and <code>1</code> on any failure. Treat non-zero as &quot;failed&quot; — do not branch on the specific value. Finer-grained exit codes may land in a minor version, so scripts that switch on the exact number will break.</p><h2 id="non-interactive-scaffolding" tabindex="-1">Non-interactive scaffolding <a class="header-anchor" href="#non-interactive-scaffolding" aria-label="Permalink to &quot;Non-interactive scaffolding&quot;">​</a></h2><p>In a TTY, <code>gsds create</code> prompts for name, framework, and category. In CI or under an AI agent, all three flags are required:</p><div class="language-sh vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">sh</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">gsds</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> create</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --name</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> revenue-overview</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --framework</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> react</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --category</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> Analytics</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br></div></div><p>If any of the three is missing, the command fails and names the missing flag — no partial widget is written.</p><p>Supported frameworks: <code>react</code>, <code>vue</code>, <code>angular</code>, <code>vanilla</code>, <code>html</code>.</p><h2 id="machine-readable-listings" tabindex="-1">Machine-readable listings <a class="header-anchor" href="#machine-readable-listings" aria-label="Permalink to &quot;Machine-readable listings&quot;">​</a></h2><p><code>gsds list --json</code> returns an object keyed by Extension type:</p><div class="language-sh vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">sh</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">gsds</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> list</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --json</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br></div></div><p>The top level is <code>{ widgets, connectors, scripts, stylesheets }</code>, not a bare array. Scripts that expect an array will fail — always index into the keyed object.</p><p>Example: preview every previewable widget:</p><div class="language-sh vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">sh</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">gsds</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> list</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --json</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> \\</span></span>
<span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">  |</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;"> jq</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -r</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> &#39;.widgets[] | select(.previewable) | .type&#39;</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> \\</span></span>
<span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">  |</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;"> xargs</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> gsds</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> preview</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --widget</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br><span class="line-number">3</span><br></div></div><h2 id="machine-readable-connector-runs" tabindex="-1">Machine-readable Connector runs <a class="header-anchor" href="#machine-readable-connector-runs" aria-label="Permalink to &quot;Machine-readable Connector runs&quot;">​</a></h2><div class="language-sh vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">sh</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">gsds</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> connector</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> test</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> revenue-feed</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --query</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> limit=</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">5</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --json</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br></div></div><p>Pair <code>--json</code> with <code>--query</code>, <code>--path-param</code>, and <code>--payload @body.json</code> for a fully non-interactive Connector run. Use this shape for smoke tests in CI.</p><h2 id="validate-the-registries-in-ci" tabindex="-1">Validate the registries in CI <a class="header-anchor" href="#validate-the-registries-in-ci" aria-label="Permalink to &quot;Validate the registries in CI&quot;">​</a></h2><p><code>gsds build --validate</code> compares <code>extensions_registry.json</code> and <code>connectors_registry.json</code> against the source files and exits <code>1</code> on drift. Wire it into your pipeline as a gate:</p><div class="language-sh vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">sh</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">gsds</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> build</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --validate</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br></div></div><p><code>--validate</code> does not rebuild <code>dist/</code>, so run plain <code>gsds build</code> locally before committing — otherwise CI catches drift you introduced yourself.</p><h2 id="sessions-in-ci" tabindex="-1">Sessions in CI <a class="header-anchor" href="#sessions-in-ci" aria-label="Permalink to &quot;Sessions in CI&quot;">​</a></h2><p><code>gsds preview</code> and <code>gsds connector test</code> require a paired session. There is no headless login flow — pairing codes come from the community UI and expire in 2 minutes. Options for CI:</p><ul><li>Keep those commands out of the pipeline (recommended). Run them locally during development, and gate CI on <code>gsds build --validate</code> instead.</li><li>Run pairing on a bootstrap machine and rely on the ~8-hour session, understanding it will expire.</li></ul><h2 id="force-the-file-based-credential-fallback" tabindex="-1">Force the file-based credential fallback <a class="header-anchor" href="#force-the-file-based-credential-fallback" aria-label="Permalink to &quot;Force the file-based credential fallback&quot;">​</a></h2><p>Set <code>GSDS_DISABLE_KEYCHAIN=1</code> in environments where no OS keychain is available. The CLI writes to <code>~/.config/gsds/credentials.json</code> at file mode <code>0600</code> and warns once on stderr. See <a href="./authenticate.html">Authenticate</a> for the full session-storage rules.</p><h2 id="next-steps" tabindex="-1">Next steps <a class="header-anchor" href="#next-steps" aria-label="Permalink to &quot;Next steps&quot;">​</a></h2><ul><li>Every flag and its default in the <a href="./reference/commands.html">Command reference</a></li><li>The full list of committed and generated files in <a href="./reference/project-files.html">Project files</a></li><li>Session model in <a href="./authenticate.html">Authenticate</a></li></ul>`,33)])])}const k=a(n,[["render",o]]);export{u as __pageData,k as default};
